using System; using System.Text.RegularExpressions; class P { static void Main() { string key = "Press <color=#ffff22>{0}</color> to continue..."; string input = "Press <color=#ffff22>SPACE</color> to continue..."; string pattern = Regex.Escape(key); pattern = Regex.Replace(pattern, @"\\?\\{(\\d+)\\?\\}", "(?<g>.*?)"); pattern = "^" + pattern + "$"; Console.WriteLine("Pattern: " + pattern); Match m = Regex.Match(input, pattern, RegexOptions.IgnoreCase); Console.WriteLine("Match: " + m.Success); } }